+      }
+      if (attempt === 2) throw new Error(`Release feed ${url}: HTTP ${response.status}`);
+    } catch (error) {
+      if (attempt === 2) throw error;
+    }
+  }
+  throw new Error(`Unavailable release feed: ${url}`);
+}
