+/** GitHub PR identity fields used by the trusted merge-policy workflow. */
+export interface AutomationPullRequest {
+  head: { ref: string; sha: string; repo: { full_name: string } | null };
+  base: { ref: string };
+  user: { login: string };
+  title: string;
+  draft: boolean;
