+
+/** An approval carries the exact reviewed commit and separately verified repository permission. */
+export interface AutomationReview {
+  id: number;
+  user: { login: string; type?: string };
+  state: string;
+  commit_id: string;
+  maintainer: boolean;
+}
+
+/** Repository-controlled expected identities; neither comes from the PR branch. */
+export interface AutomationPolicyOptions {
+  repository: string;
+  releaseActor: string;
+  renovateActor: string;
+}
+
+/** Reject impersonation and unresolved maintenance while preserving checked bot auto-merges. */
+export function automationPolicy(pr: AutomationPullRequest, reviews: readonly AutomationReview[], options: AutomationPolicyOptions): string | null {
+  const head = pr.head.ref;
+  const failed = head === "maintenance/failed-updates" || head.startsWith("maintenance/failed-updates/");
+  if (failed) return "Failed maintenance candidates cannot merge; fix or split the failing updates first.";
+  const component = head === "maintenance/component-reviews" || pr.title === "chore(components): scaffold upstream component reviews";
+  const version = head.startsWith("changeset-release/") || pr.title.startsWith("chore: version packages");
+  const renovate = head.startsWith("renovate/") || pr.title === "chore(deps): prepare weekly maintenance";
+  if (!component && !version && !renovate) return null;
+  if (pr.base.ref !== "main" || pr.head.repo?.full_name !== options.repository) return "Automation PRs must originate in this repository and target main.";
+  const actor = version ? options.releaseActor : options.renovateActor;
+  if (pr.user.login.toLowerCase() !== actor.toLowerCase()) return "Automation PR author does not match the configured bot identity.";
+  if (version && (head !== "changeset-release/main" || pr.title !== "chore: version packages")) return "Version PR branch/title does not match the authenticated Changesets flow.";
+  if (renovate && head !== "renovate/weekly-maintenance") return "Only the consolidated weekly Renovate branch may use automated maintenance merging.";
+  if (!component) return null;
+  if (head !== "maintenance/component-reviews") return "Component follow-up must use its dedicated review branch.";
+  if (pr.draft) return "Component follow-up is still a draft and requires implementation and human review.";
+  if (pr.auto_merge != null) return "Component follow-up must be merged manually, not through auto-merge.";
+  const latest = new Map<string, AutomationReview>();
+  for (const review of [...reviews].sort((left, right) => left.id - right.id)) {
+    if (review.state === "COMMENTED" || !review.maintainer || review.user.type === "Bot" || review.user.login.toLowerCase() === pr.user.login.toLowerCase()) continue;
